<script setup lang="ts">
import {computed} from 'vue';import {date,ton,label} from '../fulfillment';
const props=defineProps<{result:any}>();
const s=computed(()=>props.result.structured||{});const forecasts=computed(()=>s.value.forecasts||s.value.forecast?[...(s.value.forecasts||[]),...(s.value.forecast?[{task:s.value.task,forecast:s.value.forecast}]:[])]:[]);
const quality:Record<string,string>={ACTUAL:'实际记录',SIMULATED:'参考测算',LOW:'可信度较低',MEDIUM:'业务参考',INSUFFICIENT:'依据不足',REFERENCE:'业务参考'};
</script>
<template><div class="analysis-data"><div v-if="s.tasks" class="task-result"><div class="data-heading"><strong>运输任务</strong><span>{{s.total}} 个 · 本次展示 {{s.tasks.length}} 个</span></div><el-table :data="s.tasks" size="small" max-height="360"><el-table-column label="任务" min-width="180"><template #default="{row}"><router-link :to="'/tracking/journeys?taskId='+row.id">{{row.businessNo}}</router-link></template></el-table-column><el-table-column label="区段" min-width="220"><template #default="{row}">{{row.origin}} → {{row.destination}}</template></el-table-column><el-table-column label="进度" width="110"><template #default="{row}">{{label(row.status)}}</template></el-table-column><el-table-column label="数量" width="95"><template #default="{row}">{{ton(row.quantityKg)}}</template></el-table-column></el-table></div><section v-for="v in forecasts" :key="v.task.id" class="forecast-card"><header><router-link :to="'/tracking/journeys?taskId='+v.task.id">{{v.task.businessNo}}</router-link><span>{{quality[v.forecast.quality]||v.forecast.quality}}</span></header><strong>{{v.forecast.eta?date(v.forecast.eta):'当前依据不足，无法给出可靠到达时间'}}</strong><p>{{v.task.origin}} → {{v.task.destination}}</p><div class="forecast-metrics"><span>剩余里程 <b>{{v.forecast.remainingKm==null?'待核实':v.forecast.remainingKm+' km'}}</b></span><span>预计延误 <b>{{v.forecast.delayMinutes==null?'待核实':v.forecast.delayMinutes+' 分钟'}}</b></span></div><ul><li v-for="f in v.forecast.factors" :key="f">{{f}}</li></ul></section><div v-if="s.signals" class="signal-results"><div class="data-heading"><strong>已收录态势</strong><span>{{s.signals.length}} 条</span></div><article v-for="v in s.signals" :key="v.id"><header><strong>{{v.name}}</strong><span :class="{active:v.active}">{{v.active?'有效期内':'待生效 / 已过期'}}</span></header><p>{{v.details}}</p><small>{{v.source}} · 观测 {{date(v.observedAt)}} · 预计影响 {{v.delayMinutes}} 分钟</small></article><p v-if="!s.signals.length" class="no-signals">暂无相关态势记录。可在全程跟踪或专题视图查看已接入的数据。</p></div><div v-if="result.links?.length" class="business-links"><router-link v-for="l in result.links" :key="l.url" :to="l.url">{{l.label}} →</router-link></div><details v-if="result.sources?.length"><summary>数据依据与更新时间</summary><p v-for="(v,i) in result.sources" :key="i">{{v.source}} · {{v.observedAt?date(v.observedAt):'业务版本记录'}}</p></details></div></template>
